 if(run){var g=new GameObject("Owned same-step physical strike impulse reproduction");DontDestroyOnLoad(g);if(!SportsProbeInputIsolation.Active)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<DodgeStrikeProbe>();}}
 DodgeMatch m;Keyboard keys;string folder,key,saved;bool had;int errors;InputSettings.BackgroundBehavior background;
