 IEnumerator Start(){keys=InputSystem.AddDevice<Keyboard>();yield return SportsProbeScene.Ensure<DodgeMatch>("TruckTrampolineDodgeball");m=FindAnyObjectByType<DodgeMatch>();yield return null;key=m.PreferenceKey;had=SportsPrefs.HasKey(key);saved=SportsPrefs.GetString(key);m.SetupScreen();m.teamA=m.teamB=1;m.option=0;m.NormalizeSetup();m.AllBots();for(int i=0;i<2;i++)m.setup.players[i].source=BowlingSource.Keyboard;if(!m.StartMatch())throw new Exception("Controlled source fixture must start");yield return new WaitForSeconds(3.1f);var ball=m.balls[0];ball.ResetBall(new Vector3(0,4,0));int before=ball.Strikes;double step=Time.fixedTimeAsDouble;ball.Strike(0,Vector3.forward,Time.fixedTime);ball.Strike(1,Vector3.back,Time.fixedTime);yield return new WaitForFixedUpdate();yield return null;var velocity=ball.body.linearVelocity;bool pass=ball.Strikes-before==1&&new Vector2(velocity.x,velocity.z).magnitude>12&&velocity.y<m.strikeLift+.5f&&velocity.y>m.strikeLift-1&&ball.Team==0;string result=(pass?"PASS ":"FAIL ")+"one ball accepts one same-step strike without cancelling horizontal or doubling vertical motion\nMEASURE step="+step+" accepted="+(ball.Strikes-before)+" team="+ball.Team+" velocity="+velocity+"\n";if(!pass)errors++;m.SetupScreen();Restore();File.WriteAllText(folder+"/result.txt",result+"ERRORS="+errors+". Explicit direct strike API/initial ball-pose physical reproduction; no injected score, human or hardware claim.");if(!Application.isEditor)Application.Quit(errors==0?0:2);}
